} catch (error) {
  const current = this.flights.get(key) === flight;
  if (current) this.flights.delete(key);
  if (!flight.controller.signal.aborted) {
    this.counters.loadErrors++;
    if (refresh) this.counters.refreshErrors++;
    if (refresh && current) this.backOff(key);
    emit(this.options.onEvent, { type: refresh ? "refresh-error" : "load-error", key, error });
  }
  throw error;
}

private backOff(key: K): void {
  const base = this.options.refreshBackoffMs;
  const entry = this.map.get(key);
  if (base === undefined || entry === undefined) return;
  entry.refreshFailures++;
  const delay = Math.min(base * 2 ** (entry.refreshFailures - 1), this.options.maxRefreshBackoffMs ?? Infinity);
  entry.refreshNotBefore = this.now() + delay;
}

