import { describe, expect, it, vi } from "vitest";
import { LruCache } from "../src/index.js";
import { flush, manualClock } from "./support.js";

describe("refresh backoff", () => {
  it("waits 50, then 100, then the 150 cap between failed refreshes; a set resets it", async () => {
    const clock = manualClock(1000);
    const c = new LruCache<string, number>({ maxEntries: 10, ttlMs: 100, staleMs: 10_000, refreshBackoffMs: 50, maxRefreshBackoffMs: 150, now: clock.now });
    c.set("k", 1);
    clock.advance(100); // stale
    const failing = vi.fn(async () => { throw new Error("db down"); });
    const read = async () => { expect(await c.getOrLoad("k", failing)).toBe(1); await flush(); };
    await read(); // refresh 1 fails -> next not before +50
    await read(); // too early: no refresh
    expect(failing).toHaveBeenCalledTimes(1);
    clock.advance(50);
    await read(); // refresh 2 fails -> +100
    clock.advance(99);
    await read();
    expect(failing).toHaveBeenCalledTimes(2);
    clock.advance(1);
    await read(); // refresh 3 fails -> min(200, 150)
    clock.advance(149);
    await read();
    expect(failing).toHaveBeenCalledTimes(3);
    c.set("k", 5); // a new entry: no backoff
    clock.advance(100);
    expect(await c.getOrLoad("k", async () => 6)).toBe(5);
    await flush();
    expect(c.peek("k")).toBe(6);
  });
});

