import type { Loader } from "./cache.js";

export function withLoadTimeout<V>(loader: Loader<V>, ms: number): Loader<V> {
  if (!(Number.isFinite(ms) && ms > 0)) throw new RangeError("ms must be a finite number > 0");
  return (signal, context) => {
    const timer = AbortSignal.timeout(ms);
    const both = AbortSignal.any([signal, timer]); // Node 20.3+
    return new Promise<V>((resolve, reject) => {
      const onAbort = () => reject(timer.aborted ? new Error(`load timed out after ${ms} ms`) : both.reason);
      if (both.aborted) return onAbort();
      both.addEventListener("abort", onAbort, { once: true });
      Promise.resolve()
        .then(() => loader(both, context)) // a sync throw becomes a rejection
        .then(resolve, reject)
        .finally(() => both.removeEventListener("abort", onAbort));
    });
  };
}

