import { describe, expect, it } from "vitest";
import { LruCache } from "../src/index.js";
import { withLoadTimeout } from "../src/load-timeout.js";

describe("withLoadTimeout", () => {
  it("a hung loader fails after the timeout, the flight is released, the next call loads again", async () => {
    const c = new LruCache<string, number>({ maxEntries: 10 });
    let seen: AbortSignal | undefined;
    const hung = withLoadTimeout<number>((s) => ((seen = s), new Promise<number>(() => {})), 30);
    const all = [c.getOrLoad("k", hung), c.getOrLoad("k", hung)];
    for (const p of all) await expect(p).rejects.toThrow(/timed out after 30 ms/);
    expect(seen!.aborted).toBe(true); // the driver was told to stop too
    expect(c.stats()).toMatchObject({ loads: 1, coalesced: 1, loadErrors: 1 });
    expect(await c.getOrLoad("k", withLoadTimeout(async () => 7, 30))).toBe(7);
  });
});

