export interface LoadContext {
  ttlMs: number | undefined; // the loader may change it (TwoLevelCache: from Redis's PTTL)
  readonly refresh: boolean; // true for a stale-while-revalidate background refresh
  isCurrent(): boolean;      // still the key's load version: no delete / set / clear since it started
}
export type Loader<V> = (signal: AbortSignal, context: LoadContext) => Promise<V> | V;

// real, src/two-level.ts
private async invalidateOthers(key: string): Promise<boolean> {
  const ok = (await this.call("publish", key, () => this.redis.publish(this.channel, JSON.stringify([this.id, key])))) !== FAILED;
  if (ok) this.counters.invalidationsSent++;
  return ok;
}
